const $ = (s, root = document) => root.querySelector(s);
const state = { file: null, text: "", result: null, config: JSON.parse(localStorage.getItem("medsight-api-config") || "{}"), projects: JSON.parse(localStorage.getItem("medsight-projects") || "[]"), activeProjectId: localStorage.getItem("medsight-active-project") || null };
