async function api(path, options={}){const r=await fetch(path,{headers:{"Content-Type":"application/json",...(options.headers||{})},...options});if(!r.ok)throw new Error((await r.json().catch(()=>({}))).error||`请求失败 ${r.status}`);return r.status===204?null:r.json()}
function saveProjects(){localStorage.setItem("medsight-projects",JSON.stringify(state.projects));if(state.activeProjectId)localStorage.setItem("medsight-active-project",state.activeProjectId)}
async function loadProjects(){try{const d=await api("/api/projects");state.projects=d.projects||[];if(!state.activeProjectId||!state.projects.some(p=>p.id===state.activeProjectId))state.activeProjectId=state.projects[0]?.id||null;saveProjects();}catch(e){console.warn("项目列表加载失败",e)}}
async function openFileResult(name){const m=$("#file-result-modal");m.classList.add("open");$("#file-result-title").textContent=name;try{const d=await api(`/api/projects/${state.activeProjectId}/files/${encodeURIComponent(name)}`);$("#file-result-status").textContent=d.file.status||"Pending";$("#file-result-content").textContent=JSON.stringify(d.parsed||{message:"No parsed result yet",file:d.file},null,2);$("#retry-file").onclick=async()=>{await api(`/api/projects/${state.activeProjectId}/files/${encodeURIComponent(name)}/retry`,{method:"POST"});await loadProjects();renderFiles();$("#file-result-status").textContent="Processing"}}catch(e){$("#file-result-status").textContent="Failed: "+e.message}}
function renderFiles(){const list=$("#file-list");if(!list)return;const project=state.projects.find(item=>item.id===state.activeProjectId);const filter=$("#file-filter")?.value||"all";const files=(project?.files||[]).filter(file=>filter==="all"||file.kind===filter);list.innerHTML=files.length?files.map(file=>`<div class="file-item"><strong>${escapeHtml(file.name)}</strong><small>${escapeHtml(file.kind)} · ${file.status||"Pending"} · ${new Date(file.uploadedAt||Date.now()).toLocaleString()}</small><button class="delete-file" data-name="${escapeHtml(file.name)}" type="button">Delete</button></div>`).join(""):"<div class=project-empty>No files</div>"}
function openPreview(name){const modal=$("#preview-modal"),frame=$("#preview-frame"),title=$("#preview-title");if(!modal||!frame)return;title.textContent=name;frame.src=`/api/projects/${state.activeProjectId}/files/${encodeURIComponent(name)}/raw`;modal.classList.add("open")}
async function selectUploadedFile(name){const project=state.projects.find(item=>item.id===state.activeProjectId);const meta=project?.files?.find(file=>file.name===name);if(!meta)return;try{const response=await fetch(`/api/projects/${state.activeProjectId}/files/${encodeURIComponent(name)}/raw`);if(!response.ok)throw new Error("Unable to load file");const blob=await response.blob();setFile(new File([blob],meta.name,{type:blob.type||"application/pdf"}));showStatus("File selected. Ready to analyze")}catch(error){showStatus(error.message,true)}}
function renderUploadedFiles(){const list=$("#uploaded-files");if(!list)return;const project=state.projects.find(item=>item.id===state.activeProjectId);const files=(project?.files||[]).filter(file=>file.kind==="pdfs"),pdfs=files,processing=project?.status==="处理中";list.innerHTML=files.length?files.map(file=>`<div class="uploaded-file"><i data-lucide="${file.kind==="pdfs"?"file-text":"image"}"></i><button class="uploaded-select" data-name="${escapeHtml(file.name)}" type="button"><strong title="${escapeHtml(file.name)}">${escapeHtml(file.name)}</strong><small>${file.status||"待解析"}</small></button><button class="uploaded-preview" data-name="${escapeHtml(file.name)}" type="button" title="预览"><i data-lucide="eye"></i></button><button class="uploaded-delete" data-name="${escapeHtml(file.name)}" type="button" title="删除"><i data-lucide="trash-2"></i></button></div>`).join(""):"";const badge=$("#current-project");if(badge)badge.textContent=project?project.name:"未选择项目";analyzeButton.disabled=!pdfs.length||processing;analyzeButton.querySelector("span").innerHTML=`<i data-lucide="${processing?"loader-circle":"sparkles"}"></i>${processing?"正在分析项目":"分析全部报告"}`;if(project?.analysisSummary&&!processing)render(project.analysisSummary);setIcons()}
$("#uploaded-files")?.addEventListener("click",async event=>{const select=event.target.closest(".uploaded-select"),preview=event.target.closest(".uploaded-preview"),remove=event.target.closest(".uploaded-delete");if(select){await selectUploadedFile(select.dataset.name)}if(preview){openPreview(preview.dataset.name)}if(remove){if(confirm("Delete this file?")){await api(`/api/projects/${state.activeProjectId}/files/${encodeURIComponent(remove.dataset.name)}`,{method:"DELETE"});await loadProjects();renderUploadedFiles();showStatus("File deleted")}}});
function renderProjects(){const q=$("#project-search").value.trim().toLowerCase(),list=$("#project-list"),rows=state.projects.filter(p=>!q||`${p.name} ${p.patientName||""}`.toLowerCase().includes(q));list.innerHTML=rows.length?rows.map(p=>`<div class="project-item ${p.id===state.activeProjectId?'active':''}" data-id="${p.id}"><span class="project-icon"><i data-lucide="folder"></i></span><div class="project-main"><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.patientName||"No patient")} · ${escapeHtml(p.status)} · ${(p.files||[]).length} files · ${new Date(p.updatedAt).toLocaleString()}</small></div><div class="project-actions"><button class="small-button open-project" data-id="${p.id}" type="button">Open</button><button class="icon-button delete-project" data-id="${p.id}" type="button"><i data-lucide="trash-2"></i></button></div></div>`).join(""): '<div class="project-empty">No projects yet</div>';renderFiles();renderUploadedFiles();setIcons()}
async function openProjects(){await loadProjects();renderProjects();projectModal.classList.add("open")};function closeProjects(){projectModal.classList.remove("open")};async function createProject(){const i=$("#project-name"),name=i.value.trim();if(!name)return i.focus();try{const p=await api("/api/projects",{method:"POST",body:JSON.stringify({name})});state.projects.unshift(p);state.activeProjectId=p.id;saveProjects();i.value="";renderProjects();showStatus(`已创建项目：${name}`)}catch(e){showStatus(e.message,true)}}
$("#projects-button")?.addEventListener("click",openProjects);$("#close-projects")?.addEventListener("click",closeProjects);$("#create-project")?.addEventListener("click",createProject);$("#project-name")?.addEventListener("keydown",e=>{if(e.key==="Enter")createProject()});$("#project-search")?.addEventListener("input",renderProjects);$("#file-filter")?.addEventListener("change",renderFiles);$("#project-list")?.addEventListener("click",async e=>{const id=e.target.closest("[data-id]")?.dataset.id;if(!id)return;if(e.target.closest(".delete-project")){if(confirm("Delete this project?")){await api(`/api/projects/${id}`,{method:"DELETE"});state.projects=state.projects.filter(p=>p.id!==id);saveProjects();renderProjects();showStatus("Project deleted")}}else if(e.target.closest(".open-project")){state.activeProjectId=id;saveProjects();renderProjects();closeProjects();showStatus("Project opened")}});$("#file-list")?.addEventListener("click",async e=>{const b=e.target.closest(".delete-file"),row=e.target.closest(".file-item");if(!state.activeProjectId)return;if(b){if(confirm("Delete this file?")){await api(`/api/projects/${state.activeProjectId}/files/${b.dataset.name}`,{method:"DELETE"});await loadProjects();renderFiles();showStatus("File deleted")}}else if(row)openFileResult(row.querySelector("strong").textContent)});$("#close-file-result")?.addEventListener("click",()=>$("#file-result-modal").classList.remove("open")); loadProjects().then(()=>openProjects());

function setFile(file) {
  if (!file) return;
  if (file.type !== "application/pdf" && !file.name.toLowerCase().endsWith(".pdf")) return showStatus("请选择 PDF 文件", true);
  if (file.size > 20 * 1024 * 1024) return showStatus("文件超过 20 MB，请压缩后重试", true);
  state.file = file; fileRow.classList.remove("empty"); $("#file-name").textContent = file.name; $("#file-meta").textContent = `${(file.size / 1024 / 1024).toFixed(2)} MB · PDF`;
  analyzeButton.disabled = false; showStatus("文件已就绪，可以开始分析"); setIcons();
}
async function uploadFiles(files){const projectId=state.activeProjectId;if(!projectId){showStatus("请先打开或创建项目",true);await openProjects();return}const selected=Array.from(files||[]);if(!selected.length)return;let uploaded=0;for(const file of selected){if(file.size>20*1024*1024){showStatus(`${file.name} 超过 20 MB`,true);continue}if(!file.name.toLowerCase().endsWith(".pdf")){showStatus(`报告分析区只支持 PDF：${file.name}`,true);continue}showStatus(`正在上传 ${file.name}…`);try{const base64=await toBase64(file);await api(`/api/projects/${projectId}/upload`,{method:"POST",body:JSON.stringify({name:file.name,size:file.size,kind:"pdf",base64})});uploaded++;if(!state.file)setFile(file)}catch(error){showStatus(`${file.name} 上传失败：${error.message}`,true)}}await loadProjects();renderFiles();renderUploadedFiles();input.value="";showStatus(uploaded?`已上传 ${uploaded} 份 PDF 报告`:"没有上传文件",uploaded===0)}
function showStatus(message, error = false) {
  status.textContent = message;
  status.classList.toggle("error", error);
  let toast = document.querySelector('#global-status-toast');
  if (!toast) {
    toast = document.createElement('div'); toast.id = 'global-status-toast';
    toast.setAttribute('role', 'status'); toast.setAttribute('aria-live', 'polite');
    document.body.appendChild(toast);
  }
  toast.className = 'global-status-toast ' + (error ? 'error' : 'success');
  toast.textContent = message;
  toast.classList.remove('hidden');
  clearTimeout(showStatus.timer);
  showStatus.timer = setTimeout(() => toast.classList.add('hidden'), 1800);
}
function resetFile() { state.file = null; state.text = ""; input.value = ""; fileRow.classList.add("empty"); $("#file-name").textContent = "尚未选择文件"; $("#file-meta").textContent = "PDF 文件将在此显示"; analyzeButton.disabled = true; showStatus("等待上传报告"); }
async function extractText(file) {
  const pdfjs = globalThis.pdfjsLib;
  if (!pdfjs) return "";
  pdfjs.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
  const pdf = await pdfjs.getDocument({ data: await file.arrayBuffer() }).promise; let text = "";
  for (let pageNo = 1; pageNo <= pdf.numPages; pageNo++) { const page = await pdf.getPage(pageNo); const content = await page.getTextContent(); text += content.items.map(item => item.str).join(" ") + "\n"; }
  return text.trim();
}
const first = (re, text, fallback = "未识别") => (text.match(re)?.[1] || fallback).trim();
function analyze(text, file) {
  const values = []; const pattern = /([\u4e00-\u9fa5A-Za-z（）()]{2,18})\s*[:：]?\s*([<>≤≥]?\s*\d+(?:\.\d+)?)\s*(mg\/L|g\/L|mmol\/L|μmol\/L|U\/L|%|次\/分|mmHg)?\s*(?:参考范围|参考值)?\s*[:：]?\s*([\d.]+\s*[-~至]\s*[\d.]+)/gi;
  let match; while ((match = pattern.exec(text)) && values.length < 8) values.push({ name: match[1], value: match[2] + (match[3] ? ` ${match[3]}` : ""), ref: match[4] || "报告原文未提供" });
  const abnormalWords = /(异常|偏高|偏低|阳性|可疑|增厚|结节|炎症|占位|未见|风险|超出|升高|降低)/; const findings = [];
  const sentences = text.split(/[。.!！\n]/).map(s => s.trim()).filter(Boolean);
  sentences.filter(s => abnormalWords.test(s)).slice(0, 5).forEach((s, i) => findings.push({ title: i === 0 ? "报告中出现需要关注的描述" : "原文提示", detail: s.slice(0, 150), high: /(阳性|占位|可疑|结节|风险)/.test(s) }));
  const diagnosis = first(/(?:诊断|检查结论|影像学表现|印象)\s*[:：]?\s*([^\n。]{4,100})/, text);
  const date = first(/(20\d{2}[年\/-]\d{1,2}[月\/-]\d{1,2}日?)/, text);
  const summary = diagnosis !== "未识别" ? `报告主要结论为“${diagnosis}”。系统整理出 ${values.length || "若干"} 个可读字段${findings.length ? `，其中 ${findings.length} 处文字需要和医生进一步确认` : "，未在文本中发现明显的风险关键词"}。` : `已读取《${file.name}》并完成初步整理。报告中包含 ${values.length || "若干"} 个可识别字段，建议结合原始影像和医生解读确认结论。`;
  const fields = [{ label: "报告文件", value: file.name }, { label: "检查日期", value: date }, { label: "诊断 / 结论", value: diagnosis }, { label: "识别页数", value: "浏览器内解析" }, { label: "指标字段", value: `${values.length} 项` }, { label: "文本长度", value: `${text.length} 字` }];
  const guidance = ["预约相关专科，携带原始 PDF 和既往检查结果。", "向医生确认每个异常描述的临床意义、是否需要复查及复查时间。", "如果出现持续胸痛、呼吸困难、意识改变等急症症状，请直接联系急救服务。"];
  return { file: file.name, summary, fields, values, findings, guidance, analyzedAt: new Date().toISOString() };
}
function findingPlainText(value) {
  let text = String(value ?? '');
  try { const parsed = JSON.parse(text); if (parsed && typeof parsed === 'object') text = String(parsed.text ?? parsed.content ?? parsed.html ?? parsed.table_body ?? text); } catch {}
  return text.replace(/<\/?[a-z][^>]*>/gi,' ').replace(/&nbsp;/gi,' ').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&amp;/gi,'&').replace(/^\s*["']?(?:text|content|html|table_body)["']?\s*:\s*["']?/i,'').replace(/\s+/g,' ').trim();
}
function groupReportFindings(result) {
  const groups = new Map();
  for (const finding of result.findings || []) {
    const detail = String(finding.detail || '');
    const legacy = detail.match(/来源[：:]\s*(.+?\.pdf)(?:[，,；;]\s*第\s*([^。；;]+?)\s*页)?/i);
    const file = finding.source?.file || legacy?.[1]?.trim() || (/\.pdf$/i.test(result.file || '') ? result.file : '来源待核对');
    const page = finding.source?.page ?? legacy?.[2];
    const title = findingPlainText(finding.title);
    const content = findingPlainText(detail.replace(/；?来源[：:][\s\S]*$/, ''));
    if (!groups.has(file)) groups.set(file, {file, items:new Map(), originalCount:0});
    const group = groups.get(file); group.originalCount++;
    const key = JSON.stringify([title,content,Boolean(finding.high)]);
    if (!group.items.has(key)) group.items.set(key,{title,content,high:finding.high,pages:new Set(),count:0});
    const item = group.items.get(key); item.count++;
    if (page != null && page !== '') item.pages.add(String(page));
  }
  return [...groups.values()];
}
function renderReportFindings(result) {
  const groups = groupReportFindings(result);
  const count = groups.reduce((sum,group)=>sum+group.items.size,0);
  $('#abnormal-count').textContent = count + ' 项 · ' + groups.length + ' 份报告';
  $('#abnormal-list').innerHTML = groups.length ? groups.map(group=>'<details class="report-finding-group"><summary><span><strong>'+escapeHtml(group.file)+'</strong><small>'+group.items.size+' 项需关注'+(group.originalCount>group.items.size?' · 合并 '+(group.originalCount-group.items.size)+' 条重复描述':'')+'</small></span><span class="report-finding-toggle">展开</span></summary><div class="report-finding-items">'+[...group.items.values()].map(item=>'<article class="abnormal '+(item.high?'high':'')+'"><i data-lucide="circle-alert"></i><div><strong>'+escapeHtml(item.title)+'</strong><p>'+escapeHtml(item.content)+'</p><small>来源页码 '+escapeHtml([...item.pages].sort((left,right)=>Number(left)-Number(right)).join('、')||'待核对')+(item.count>1?' · '+item.count+' 处相同描述':'')+'</small></div></article>').join('')+'</div></details>').join('') : '<div class="abnormal">暂无需要关注的描述，请以医生核对原始报告的结果为准。</div>';
  document.querySelectorAll('.report-finding-group').forEach(group=>group.addEventListener('toggle',()=>{group.querySelector('.report-finding-toggle').textContent=group.open?'收起':'展开';}));
}

function render(result) {
  state.result = result; $("#result-empty").classList.add("hidden"); $("#result-content").classList.remove("hidden"); $("#result-title").textContent = result.file.replace(/\.pdf$/i, "") + " · 分析结果"; $("#summary").textContent = result.summary;
  $("#field-grid").innerHTML = result.fields.map(f => `<div class="field"><label>${f.label}</label><strong>${escapeHtml(f.value)}</strong></div>`).join("");
  renderReportFindings(result);
  $("#guidance-list").innerHTML = result.guidance.map(item => `<li>${escapeHtml(item)}</li>`).join(""); setIcons();
}

async function enhanceWithAgents(result) {
  const payload = { projectId: state.activeProjectId, fileName: state.file.name, text: state.text, pdfBase64: await toBase64(state.file), config: state.config };
  const response = await fetch("/api/analyze", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
  if (!response.ok) throw new Error((await response.json()).error || "服务端分析失败");
  const data = await response.json();
  if (data.text && data.text !== state.text) { state.text = data.text; result = analyze(state.text, state.file); }
  if (data.ai) { result.summary = data.ai.summary || result.summary; result.findings = Array.isArray(data.ai.findings) ? data.ai.findings : result.findings; result.guidance = Array.isArray(data.ai.guidance) ? data.ai.guidance : result.guidance; result.agentMeta = data.meta; }
  return result;
}
function toBase64(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1]); reader.onerror = reject; reader.readAsDataURL(file); }); }
function escapeHtml(value) { return String(value).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c])); }
function download(type) { if (!state.result) return; const r = state.result; let body, name, mime; if (type === "json") { body = JSON.stringify(r, null, 2); name = "medical-report-analysis.json"; mime = "application/json"; } else { body = `# ${r.file} · 医学报告分析\n\n## 一页摘要\n${r.summary}\n\n## 关键字段\n${r.fields.map(f => `- ${f.label}：${f.value}`).join("\n")}\n\n## 需要关注\n${r.findings.length ? r.findings.map(f => `- ${f.title}：${f.detail}`).join("\n") : "- 未发现明显异常关键词"}\n\n## 就医沟通准备\n${r.guidance.map(g => `- ${g}`).join("\n")}\n\n> 本结果仅用于信息整理，不构成医疗诊断。`; name = "medical-report-analysis.md"; mime = "text/markdown"; } const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([body], { type: mime })); a.download = name; a.click(); URL.revokeObjectURL(a.href); }

dropzone.addEventListener("click", () => input.click()); $("#choose-button").addEventListener("click", e => { e.stopPropagation(); input.click(); }); input.addEventListener("change", e => uploadFiles(e.target.files)); ["dragenter", "dragover"].forEach(type => dropzone.addEventListener(type, e => { e.preventDefault(); dropzone.classList.add("dragover"); })); ["dragleave", "drop"].forEach(type => dropzone.addEventListener(type, e => { e.preventDefault(); dropzone.classList.remove("dragover"); })); dropzone.addEventListener("drop", e => uploadFiles(e.dataTransfer.files)); $("#remove-file").addEventListener("click", resetFile);
async function pollProjectAnalysis(){for(let attempt=0;attempt<240;attempt++){const data=await api(`/api/projects/${state.activeProjectId}/analysis-summary`);await loadProjects();renderUploadedFiles();const done=data.files.filter(file=>file.kind==="pdfs"&&file.status==="已完成").length,total=data.files.filter(file=>file.kind==="pdfs").length;showStatus(`正在分析 ${done}/${total} 份报告…`);if(data.status!=="处理中"){progress.classList.remove("active");if(data.summary){render(data.summary);showStatus("全部报告已汇总，请审核异常项与来源")}else showStatus(data.error||"项目分析失败",true);renderUploadedFiles();return}await new Promise(resolve=>setTimeout(resolve,3000))}progress.classList.remove("active");showStatus("分析仍在后台进行，可稍后重新打开项目查看",true)}
analyzeButton.addEventListener("click",async()=>{if(!state.activeProjectId)return showStatus("请先打开一个项目",true);analyzeButton.disabled=true;progress.classList.add("active");showStatus("正在创建批量解析任务…");try{await api(`/api/projects/${state.activeProjectId}/analyze-all`,{method:"POST",body:"{}"});await pollProjectAnalysis()}catch(error){progress.classList.remove("active");showStatus(`无法启动分析：${error.message}`,true);await loadProjects();renderUploadedFiles()}});
$("#download-md").addEventListener("click", () => download("md")); $("#download-json").addEventListener("click", () => download("json")); setIcons();
const settingsModal = $("#settings-modal");
function openSettings() { const c = state.config; $("#deepseek-key").value = c.deepseek?.key || ""; $("#deepseek-url").value = c.deepseek?.url || "https://api.deepseek.com"; $("#mineru-key").value = c.mineru?.token || ""; $("#mineru-url").value = c.mineru?.url?.replace("/api/v1/file-urls/batch-upload","/api/v4") || "https://mineru.net/api/v4"; settingsModal.classList.add("open"); settingsModal.setAttribute("aria-hidden", "false"); }
function closeSettings() { settingsModal.classList.remove("open"); settingsModal.setAttribute("aria-hidden", "true"); }
function readConfig() { return { deepseek: { key: $("#deepseek-key").value.trim(), url: $("#deepseek-url").value.trim() || "https://api.deepseek.com" }, mineru: { token: $("#mineru-key").value.trim(), url: $("#mineru-url").value.trim() || "https://mineru.net/api/v4" } }; }
$("#settings-button").addEventListener("click", openSettings); $("#close-settings").addEventListener("click", closeSettings); $("#cancel-settings").addEventListener("click", closeSettings);
