function renderIndicators(items){originalIndicators=items||[];const dims=['待分类','前置因素','诱发因素','介质因素','同化代谢','代谢转换与消除','结构完整性','防御与修护','传递系统','传输系统','能量生成','睡眠与放松','运动与活动','营养和水分','压力','人际社交关系'];const groups=new Map();(items||[]).forEach(x=>{const key=x.reportType||'其他报告';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(x)});originalIndicators=[...groups.values()].flat();let html='';for(const [type,group] of groups){html+=`<div class="indicator-group"><div class="indicator-group-title"><strong>${escapeHtml(type)}</strong><small>${group.length} 条候选指标</small></div>${group.map((x,i)=>{const tone=x.conflict?'conflict':x.duplicate?'duplicate':x.status==='异常'?'abnormal':'normal';return `<div class="field indicator-card ${tone}" data-file="${escapeHtml(x.source?.file||'')}" data-page="${x.source?.page||''}"><label class="indicator-name"><input type="checkbox" data-indicator-check="${i}"><span>${escapeHtml(x.name||'未命名指标')}</span></label><input data-indicator="${i}" value="${escapeHtml(x.name||'')}" aria-label="指标名称"><textarea data-indicator-value="${i}" aria-label="指标值">${escapeHtml(x.value||'')}</textarea><select data-indicator-dimension="${i}" aria-label="所属维度">${dims.map(d=>`<option ${d===(x.dimension||'待分类')?'selected':''}>${d}</option>`).join('')}</select><select data-indicator-review="${i}" aria-label="审核状态"><option ${x.reviewStatus==='待审核'?'selected':''}>待审核</option><option ${x.reviewStatus==='已确认'?'selected':''}>已确认</option><option ${x.reviewStatus==='已排除'?'selected':''}>已排除</option><option ${x.reviewStatus==='需补充'?'selected':''}>需补充</option></select><span class="indicator-badge">${x.conflict?'结果冲突':x.duplicate?'重复指标':x.status==='异常'?(x.severity||'异常'):'未见明显异常'}</span><small class="indicator-source">来源：${escapeHtml(x.source?.file||'未知文件')}<br>第 ${x.source?.page||'?'} 页</small></div>`}).join('')}</div>`}$("#indicator-list").innerHTML=html||'<p class="project-empty">暂无指标，请先提取</p>'}
