function renderEvidencePage(items){window.__evidenceItems=items||[];const esc=escapeHtml;const cards=(items||[]).map((x,i)=>`<article class="evidence-card ${x.reviewStatus==='已确认'?'confirmed':x.reviewStatus==='已排除'?'excluded':''}" data-evidence-index="${i}"><div class="evidence-head"><strong>${esc(x.dimension||'待分类')}</strong><span>${esc(x.type||'指标证据')}</span><select data-evidence-review><option ${x.reviewStatus==='待审核'?'selected':''}>待审核</option><option ${x.reviewStatus==='已确认'?'selected':''}>已确认</option><option ${x.reviewStatus==='需补充'?'selected':''}>需补充</option><option ${x.reviewStatus==='已排除'?'selected':''}>已排除</option></select></div><label>判断说明<textarea data-evidence-reason>${esc(x.reasoning||'')}</textarea></label><p><b>结论：</b>${esc(x.claim||'')}</p><div class="evidence-indicators">${(x.indicators||[]).map(v=>`${esc(v.name)}：${esc(v.value||'')}（${esc(v.status||'待确认')}）`).join('、')}</div><div class="evidence-sources">${(x.sources||[]).map(v=>`来源：${esc(v.file||'未知文件')} · 第 ${v.page||'?'} 页`).join('<br>')||'暂无来源页码'}</div></article>`).join('');return cards||'<p class="project-empty">暂无举证草稿，请先点击“生成举证草稿”。</p>'}
function renderMatrixPage(d){if(!d.confirmedIndicatorCount){const draft=d.matrixDraft,groups=(draft?.dimensions||[]).map(x=>`<article class="matrix-dimension"><div class="matrix-dimension-head"><strong>${escapeHtml(x.name)}</strong><span class="matrix-status">矩阵草稿 · 待审核</span></div><p>${escapeHtml(x.assessment)}</p>${(x.items||[]).slice(0,8).map(i=>`<div class="matrix-indicator"><span>${escapeHtml(i.name)}：${escapeHtml(i.value||'')}</span><small>${escapeHtml(i.source?.file||'未知文件')} · 第 ${i.source?.page||'?'} 页</small></div>`).join('')}</article>`).join('');$("#matrix-page-content").innerHTML=`<div class="workflow-placeholder matrix-draft-empty"><div><strong>${draft?'已生成矩阵草稿，等待人工确认':'当前暂无已确认指标'}</strong><p>${draft?'以下内容基于候选指标生成，只能作为草稿，不能进入综合分析或 PPT。':'请先完成 PDF / 截图解析，再在病例审核中提取并确认指标。'}</p><button class="primary-button" id="generate-matrix-draft" type="button">${d.candidateIndicatorCount?(draft?'重新生成矩阵草稿':'生成矩阵草稿'):'返回报告分析'}</button></div></div>${groups?`<section class="matrix-section"><h3>候选矩阵草稿</h3><div class="matrix-dimensions">${groups}</div></section>`:''}`;$("#generate-matrix-draft")?.addEventListener('click',generateMatrixDraft);return;}const section=(title,body)=>`<section class="matrix-section"><h3>${title}</h3>${body}</section>`;const source=s=>s?.file?`<small class="matrix-source">来源：${escapeHtml(s.file)} · 第 ${s.page||'?'} 页</small>`:'';const dims=(d.dimensions||[]).map(x=>`<article class="matrix-dimension"><div class="matrix-dimension-head"><strong>${escapeHtml(x.name)}</strong><span class="matrix-status">${escapeHtml(x.assessmentStatus||'待人工确认')}</span></div><p>${escapeHtml(x.assessment||'')}</p>${(x.items||[]).map(i=>`<div class="matrix-indicator"><span>${escapeHtml(i.name)}：${escapeHtml(i.value||'')}</span>${source(i.source)}</div>`).join('')}${(x.sources||[]).map(source).join('')}</article>`).join('');const roots=(d.rootMechanisms||[]).map(x=>`<article class="matrix-insight"><strong>${escapeHtml(x.name)}</strong><p>${escapeHtml(x.detail)}</p>${(x.sources||[]).map(source).join('')}</article>`).join('')||'<p class="project-empty">暂无已确认异常可归纳。</p>';const factors=(d.threeFactors||[]).map(x=>`<article class="matrix-insight"><strong>${escapeHtml(x.name)}</strong><p>${escapeHtml(x.detail)}</p>${(x.sources||[]).map(source).join('')}</article>`).join('');const timeline=(d.timeline||[]).map(x=>`<div class="timeline-item"><strong>${escapeHtml(x.date||x.time||'待补充')}</strong><span>${escapeHtml(x.title||x.event||x.description||'')}</span>${(x.sources||[]).map(source).join('')}</div>`).join('')||'<p class="project-empty">暂无病例时间线，请在病例审核中补充。</p>';const evidence=(d.evidence||[]).filter(x=>x.reviewStatus==='已确认');$("#matrix-page-content").innerHTML=`<div class="evidence-tabs"><button class="evidence-tab active" data-evidence-tab="indicators">指标证据</button><button class="evidence-tab" data-evidence-tab="dimensions">维度证据</button></div><div id="evidence-indicators-panel">${renderEvidencePage(d.evidence||[])}</div><div id="evidence-dimensions-panel" class="hidden">${section('维度综合评估',`<div class="matrix-dimensions">${dims}</div>`)+section('核心根源机制',`<div class="matrix-insights">${roots}</div>`)+section('三因素分析',`<div class="matrix-insights factors">${factors}</div>`)+section('健康事件时间线',`<div class="timeline">${timeline}</div>`)+`<p class="matrix-disclaimer">${escapeHtml(d.disclaimer||'')}</p>`}</div><div class="evidence-actions"><button class="secondary-button" id="generate-evidence" type="button">生成举证草稿</button><button class="primary-button" id="save-evidence" type="button">保存举证审核</button><span>已确认举证：${evidence.length} 条</span></div>`;document.querySelectorAll('[data-evidence-tab]').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('[data-evidence-tab]').forEach(x=>x.classList.toggle('active',x===tab));$('#evidence-indicators-panel').classList.toggle('hidden',tab.dataset.evidenceTab!=='indicators');$('#evidence-dimensions-panel').classList.toggle('hidden',tab.dataset.evidenceTab!=='dimensions')}));$('#generate-evidence').addEventListener('click',generateEvidence);$('#save-evidence').addEventListener('click',saveEvidence);setIcons()}
