function readableMatrixText(value){let text=String(value||'').trim();const labels={patient:'个人信息',history:'病史资料',name:'姓名',gender:'性别',age:'年龄',symptoms:'症状表现',allergies:'过敏情况',medications:'目前用药',visits:'就诊记录',diagnosis:'诊断结果',timeline:'健康时间线',date:'日期',time:'时间',department:'就诊科室',doctor:'接诊医生',chiefComplaint:'主要问题',presentIllness:'现病经过',pastHistory:'既往情况',familyHistory:'家族情况'};try{const parsed=JSON.parse(text);if(parsed&&typeof parsed==='object'){const parts=[];const walk=(item,prefix='')=>{if(item==null||item==='')return;if(Array.isArray(item))return item.forEach(entry=>walk(entry,prefix));if(typeof item==='object')return Object.entries(item).forEach(([key,nested])=>walk(nested,prefix+(prefix?' ':'')+(labels[key]||key)));parts.push(prefix+' '+item)};walk(parsed);return parts.join('；')}}catch{}text=text.replace(/^(patient|history|symptoms|allergies|medications|visits|diagnosis|timeline)(?:\.|：|:)?\s*/i,m=>(labels[m.replace(/[：:.\s]/g,'').toLowerCase()]||m)+' ');for(const [key,label] of Object.entries(labels))text=text.replace(new RegExp('(^|[\s；])'+key+'(?=\s|：|:)','gi'),'$1'+label+' ');return text.replace(/[{}\[\]"]+/g,'').replace(/\s+/g,' ').trim()}
const matrixCoreDefinitions = [
  {id:'integrity',title:'结构完整性'}, {id:'assimilation',title:'同化代谢'},
  {id:'conversion',title:'代谢转化与消除'}, {id:'signal',title:'传递系统'},
  {id:'defense',title:'防御与修复'}, {id:'transport',title:'传输系统'}, {id:'energy',title:'能量生成'}
];
let matrixTextBusy = false;
function matrixNotice(message, tone = 'success') {
  let notice = document.querySelector('#matrix-notice');
  if (!notice) {
    notice = document.createElement('div'); notice.id = 'matrix-notice';
    notice.setAttribute('role','status'); notice.setAttribute('aria-live','polite');
    document.body.appendChild(notice);
  }
  notice.className = 'matrix-notice ' + tone;
  notice.classList.remove('hidden');
  notice.textContent = message;
  clearTimeout(matrixNotice.timer);
  matrixNotice.timer = setTimeout(() => notice.classList.add('hidden'), 1800);
}
function renderMatrixWorkspace(workspace){const esc=escapeHtml;const cleanFacts=(section)=>{const seen=new Set();return (section.candidateFacts||[]).filter(item=>{const text=readableMatrixText(item.text||'');if(!text||seen.has(text))return false;seen.add(text);return true}).slice(0,6)};const storyText=(section)=>{const facts=cleanFacts(section).map(item=>readableMatrixText(item.text||'')).filter(Boolean);const summary=readableMatrixText(section.summary||section.interpretation||'');return summary||facts.slice(0,4).join('；')};const sections=(workspace?.sections||[]).map((section,index)=>{const facts=cleanFacts(section).map(fact=>'<div class="matrix-candidate"><span>'+esc(fact.title||'病史资料')+'</span><div>'+esc(readableMatrixText(fact.text||''))+'<small>'+esc(fact.sourceType==='manual'?'文字稿':'截图与病例资料')+'</small></div></div>').join('');const summary=section.summary||section.interpretation||'';const storySummary=section.sectionId==='story'?storyText(section):'';return '<details class="matrix-workspace-section" data-kind="'+esc(section.kind||'factor')+'"><summary><div class="matrix-section-summary"><div class="matrix-section-title"><span class="matrix-section-index">'+String(index+1).padStart(2,'0')+'</span><h3>'+esc(section.title)+'</h3></div><div class="matrix-section-meta"><span class="matrix-section-status">'+esc(section.reviewStatus||'待审核')+'</span><i class="matrix-section-chevron" data-lucide="chevron-down"></i></div></div></summary><div class="matrix-section-body">'+(section.sectionId==='story'?(storySummary?'<div class="matrix-story-summary">'+esc(storySummary)+'</div>':'<div class="matrix-empty-fact">暂无已识别内容</div>'):(facts?'<div class="matrix-candidates">'+facts+'</div>':'<div class="matrix-empty-fact">暂无已识别内容</div>'))+'<textarea data-matrix-summary="'+esc(section.sectionId)+'" placeholder="仅在识别不完整时补充一句">'+esc(summary)+'</textarea><div class="matrix-section-footer"><small>来源 '+(section.sources||[]).length+' 个 · 内容 '+cleanFacts(section).length+' 条</small><div><button class="secondary-button" data-matrix-status-action="需补充" data-save-matrix-section="'+esc(section.sectionId)+'" type="button">需补充</button><button class="primary-button" data-matrix-status-action="已确认" data-save-matrix-section="'+esc(section.sectionId)+'" type="button">确认本区</button></div></div></div></details>'}).join('');const sourceFiles=(state.projects.find(x=>x.id===state.activeProjectId)?.files||[]).filter(x=>x.kind==='screenshots');const core={...(workspace?.core||{}),central:'心理、精神、情绪',fields:matrixCoreDefinitions.map(definition=>({...((workspace?.core?.fields||[]).find(field=>field.id===definition.id)||{}),...definition}))};const coreFields=(core.fields||[]).map(field=>'<label class="matrix-core-field" data-core-position="'+esc(field.id)+'"><strong>'+esc(field.title)+'</strong><textarea data-core-field="'+esc(field.id)+'" placeholder="可直接填写，或粘贴文字稿后自动归类">'+esc(field.content||'')+'</textarea><em>'+esc(field.reviewStatus||'待审核')+'</em></label>').join('');$('#matrix-page-content').innerHTML='<div class="matrix-workspace-toolbar"><div><strong>系统先整理，医生只确认</strong><p>默认只显示系统从截图、病例和文字稿整理出的内容；只有识别不完整时才需要补一句。</p></div><span class="source-count">已上传截图 '+sourceFiles.length+' 张</span></div><div class="matrix-text-entry"><textarea id="matrix-text-input" placeholder="可粘贴一段问诊记录或口述稿，系统会自动归类"></textarea><button class="secondary-button" id="matrix-text-generate" type="button"><i data-lucide="file-text"></i>整理文字稿</button></div><div id="matrix-source-files" class="matrix-source-files"></div><section class="matrix-core-panel"><div><span class="matrix-core-kicker">中央功能环 · 七个填写区</span><h3>'+esc(core.central)+'</h3><p>七个填写框已预留，可直接输入并保存；没有资料时留空，之后也可通过文字稿补入。</p><button class="secondary-button" id="save-matrix-core" type="button">保存中央环</button></div><div class="matrix-core-fields"><div class="matrix-core-center"><strong>心理 · 精神 · 情绪</strong><small>核心影响因素</small></div>'+(coreFields||'<span class="matrix-empty-fact">暂无已整理内容</span>')+'</div></section><div class="matrix-workspace-sections">'+(sections||'<p class="project-empty">暂无矩阵分区。</p>')+'</div>';document.querySelector('#save-matrix-core')?.addEventListener('click',async()=>{const next={...core,fields:(core.fields||[]).map(field=>({...field,content:document.querySelector('[data-core-field=\"'+CSS.escape(field.id)+'\"]')?.value||''}))};try{await api('/api/projects/'+state.activeProjectId+'/matrix-workspace',{method:'PUT',body:JSON.stringify({workspace:{core:next}})});matrixNotice('七个填写区已保存，请审核。');await openMatrixPage()}catch(e){matrixNotice('保存失败：'+e.message,'error')}});document.querySelectorAll('[data-save-matrix-section]').forEach(button=>button.addEventListener('click',async()=>{const id=button.dataset.saveMatrixSection;const section=(workspace.sections||[]).find(x=>x.sectionId===id);section.summary=document.querySelector('[data-matrix-summary="'+CSS.escape(id)+'"]')?.value||'';section.interpretation=section.summary;section.reviewStatus=button.dataset.matrixStatusAction||section.reviewStatus;try{await api('/api/projects/'+state.activeProjectId+'/matrix-workspace/sections/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({section})});showStatus(section.reviewStatus==='已确认'?'本区已确认':'已标记为需补充');await openMatrixPage()}catch(e){showStatus('保存失败：'+e.message,true)}}));setIcons()}
