function renderSynthesis(d){synthesisSnapshot={projectId:state.activeProjectId,dataVersion:d.dataVersion};const source=s=>s?.file?`<small class="matrix-source">来源：${escapeHtml(s.file)} · 第 ${s.page||'?'} 页</small>`:'';const cards=(d.dimensions||[]).map(x=>`<article class="synthesis-card ${x.abnormalCount?'has-abnormal':'no-abnormal'}"><div class="matrix-dimension-head"><strong>${escapeHtml(x.name)}</strong><span class="matrix-status">${escapeHtml(x.assessmentStatus|| (x.abnormalCount?'需关注':'未见明显异常'))}</span></div><p>${escapeHtml(x.assessment)}</p><small>${x.count} 条指标 · ${x.abnormalCount} 条异常</small>${(x.sources||[]).map(source).join('')}</article>`).join('');const findings=(d.priorityFindings||[]).map(x=>`<article class="synthesis-finding"><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.detail)}</p>${source(x.source)}</article>`).join('')||'<p class="project-empty">暂无已确认异常重点。</p>';const sug=(d.confirmedSuggestions||[]).map(x=>`<article class="synthesis-suggestion"><span>${escapeHtml(x.category)} · ${escapeHtml(x.type)}</span><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.editableContent||x.content||'')}</p></article>`).join('')||'<p class="project-empty">暂无已确认建议，不能进入 PPT。</p>';const review=d.synthesisReview||{status:d.reviewStatus||'待审核',note:''};$("#synthesis-page-content").innerHTML=`<div class="synthesis-overview"><div><span>已确认指标</span><strong>${d.confirmedIndicatorCount}</strong></div><div><span>异常指标</span><strong>${d.abnormalCount}</strong></div><div><span>已确认建议</span><strong>${d.confirmedSuggestionCount}</strong></div><div><span>当前状态</span><strong>${escapeHtml(review.status)}</strong></div></div><section class="matrix-section"><h3>整体情况</h3><div class="synthesis-summary">${escapeHtml(d.summary)}</div></section><section class="matrix-section"><h3>维度综合结果</h3><div class="synthesis-grid">${cards||'<p class="project-empty">暂无维度数据。</p>'}</div></section><section class="matrix-section"><h3>优先关注的异常</h3><div class="synthesis-grid">${findings}</div></section><section class="matrix-section"><h3>已确认健康建议</h3><div class="synthesis-grid">${sug}</div></section><section class="synthesis-review-box"><h3>综合分析人工确认</h3><textarea id="synthesis-review-note" placeholder="可填写审核备注">${escapeHtml(review.note||'')}</textarea><div><button class="primary-button" id="save-synthesis-review" type="button">${review.status==='已确认'?'更新确认':'确认综合分析'}</button><span class="connection-status">当前状态：${escapeHtml(review.status)}</span></div></section><p class="matrix-disclaimer">${escapeHtml(d.disclaimer||'')}</p>`;$("#save-synthesis-review").addEventListener('click',saveSynthesisReview);setIcons()}
async function openSynthesisPage(){if(!state.activeProjectId)return showStatus('请先打开一个项目',true);try{const d=await api(`/api/projects/${state.activeProjectId}/synthesis`);renderSynthesis(d)}catch(e){if(/项目不存在|项目数据已损坏/.test(e.message)){await loadProjects();renderProjects();setWorkflowStep(1);showStatus('当前项目已不存在，请从项目列表重新打开',true)}else showStatus(`综合分析加载失败：${e.message}`,true)}}
async function generateSynthesis(){const button=$("#refresh-synthesis");button.disabled=true;await openSynthesisPage();button.disabled=false;showStatus('综合分析已更新')}
async function saveSynthesisReview(){if(!state.activeProjectId)return;try{const note=$("#synthesis-review-note")?.value.trim()||'';await api(`/api/projects/${state.activeProjectId}/synthesis`,{method:'PUT',body:JSON.stringify({status:'已确认',note,dataVersion:synthesisSnapshot?.projectId===state.activeProjectId?synthesisSnapshot.dataVersion:null})});showStatus('综合分析已确认并保存');await openSynthesisPage()}catch(e){showStatus(`综合分析保存失败：${e.message}`,true);await openSynthesisPage()}}
function renderPptTemplate(data){
  const esc=escapeHtml;
  $("#ppt-template-content").innerHTML=`<div class="ppt-template-summary"><strong>${esc(data.templateName)}</strong><span>${data.slideCount} 页 · 竖版</span><span>${data.ready?'可导出':'待审核'}</span></div><p>${esc(data.disclaimer)}</p><div class="portrait-grid">${(data.slides||[]).map(page=>`<article class="portrait-sheet" aria-label="第 ${page.number} 页 ${esc(page.title)}"><img class="portrait-logo" src="/assets/ppt/logo.png" alt="敏医康"><div class="portrait-tagline">专注过敏诊疗 · 托举健康人生</div>${page.kind==='cover'?`<div class="portrait-cover"><span>${esc(page.subtitle)}</span><h3>过敏健康改善<br>指导方案</h3><div>个性化健康管理<small>已审核资料 · 行动建议 · 随访调整</small></div></div>`:`<h3 class="portrait-title">${esc(page.title)}</h3>${page.blocks.map(block=>`<div class="portrait-block" style="left:${block.x/7.5*100}%;top:${block.y/10.8333*100}%;width:${block.w/7.5*100}%;height:${block.h/10.8333*100}%">${esc(block.text)}</div>`).join('')}`}<footer class="portrait-footer">敏医康 · 仅供健康管理沟通<span>${page.number} / ${data.slideCount}</span></footer></article>`).join('')}</div>`;
}
async function openPptTemplate(){if(!state.activeProjectId)return showStatus('请先打开一个项目',true);try{renderPptTemplate(await api(`/api/projects/${state.activeProjectId}/ppt-template`))}catch(e){showStatus(`PPT 模板加载失败：${e.message}`,true)}}
async function exportPpt(){if(!state.activeProjectId)return showStatus('请先打开一个项目',true);const b=$("#export-ppt");b.disabled=true;$("#export-status").textContent='正在生成 PPT…';try{const d=await api(`/api/projects/${state.activeProjectId}/export-ppt`,{method:'POST',body:'{}'});const a=document.createElement('a');a.href=`/api/projects/${state.activeProjectId}/exports/${encodeURIComponent(d.name)}`;a.download=d.name;a.click();$("#export-status").textContent=`已生成 ${d.name}，共 ${d.slideCount} 页。`;await openExportPage();showStatus('PPT 已生成并开始下载')}catch(e){$("#export-status").textContent=e.message;showStatus(`PPT 导出失败：${e.message}`,true)}finally{b.disabled=false}}
async function openExportPage(){if(!state.activeProjectId)return showStatus('请先打开一个项目',true);try{const d=await api(`/api/projects/${state.activeProjectId}/exports`);const rows=(d.exports||[]).map(x=>'<div class="export-history-row"><span>'+escapeHtml(x.name)+'</span><small>'+new Date(x.createdAt).toLocaleString()+' · '+(x.slideCount||'-')+' 页 · '+(x.qa?.preview?'预览已生成':'未生成预览')+'</small>'+(x.previewName?'<button class="small-button export-preview" data-preview="'+escapeHtml(x.previewName)+'" type="button">预览</button>':'')+'<a class="small-button" href="/api/projects/'+encodeURIComponent(state.activeProjectId)+'/exports/'+encodeURIComponent(x.name)+'">下载 PPTX</a></div>').join('');$("#export-history").innerHTML=d.exports?.length?'<h3>历史导出</h3>'+rows:'<p>暂无历史导出文件。</p>'}catch(e){$("#export-history").textContent=e.message}}
async function exportJson(){if(!state.activeProjectId)return;const d=await api(`/api/projects/${state.activeProjectId}/export-json`);downloadText(JSON.stringify(d,null,2),`${state.activeProjectId}-structured.json`,'application/json')}
async function exportSources(){if(!state.activeProjectId)return;const d=await api(`/api/projects/${state.activeProjectId}/source-directory`);downloadText(JSON.stringify(d,null,2),`${state.activeProjectId}-sources.json`,'application/json')}
function downloadText(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function setWorkflowStep(step){step=Number(step);document.querySelectorAll('.workflow-tab').forEach(x=>x.classList.toggle('active',x.dataset.step===String(step)));document.querySelectorAll('.workflow-step').forEach(x=>x.classList.toggle('hidden',!x.classList.contains(`workflow-step-${step}`)));if(step===2)openMatrixPage();if(step===3)openSynthesisPage();if(step===4)openSuggestionsPage();if(step===5)openPptTemplate();if(step===6)openExportPage();}
