async function loadOutputProfile(){if(!state.activeProjectId)return;try{const d=await api('/api/projects/'+state.activeProjectId+'/output-profile');const p=d.profile||{};['audience','ageGroup','missingData'].forEach(k=>{const el=$('#output-'+(k==='missingData'?'missing-data':k));if(el)el.value=p[k]||el.value});}catch(e){}}
