function renderModuleList(modules=[]){const el=$('#module-list');if(!el)return;el.innerHTML=modules.length?modules.map(m=>'<span class="'+(m.status==='missing_data'?'missing':'')+'">'+escapeHtml(m.moduleTitle||m.title||m.moduleId||'模块')+(m.status==='missing_data'?' · 待补充':'')+'</span>').join(''):'<span>旧项目模式：使用 suggestions[]</span>'}
function renderSuggestions(data){
  suggestionState={...data,suggestions:data.suggestions||[],modules:data.modules||[],combinationAnalysis:data.combinationAnalysis||[]};renderModuleList(suggestionState.modules);
  const confirmedIndicators=Number(data.confirmedIndicatorCount||0),candidateIndicators=Number(data.candidateIndicatorCount||data.basedOnIndicatorCount||0);
  $("#suggestion-count").textContent=confirmedIndicators?`${suggestionState.suggestions.length} 条建议 · ${suggestionState.suggestions.filter(x=>x.reviewStatus==='已确认').length} 条已确认`:`暂无建议：${candidateIndicators?`有 ${candidateIndicators} 条候选指标，但尚未人工确认`:'暂无候选指标，请先完成报告分析和指标审核'}`;
  $("#combination-analysis").innerHTML=suggestionState.combinationAnalysis.length?suggestionState.combinationAnalysis.map(x=>`<div class="combination-card"><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.detail)}</p></div>`).join(''):'<div class="combination-card muted">暂无可生成的异常组合。</div>';
  const card=(x,i)=>`<article class="suggestion-card ${x.category==='必须回避'?'avoid':x.category==='建议调整'?'adjust':'optional'}" data-suggestion-index="${i}"><div class="suggestion-card-head"><span class="suggestion-category">${escapeHtml(x.category||'建议调整')}</span><span class="suggestion-type">${escapeHtml(x.module||x.type||'')}</span><label class="suggestion-review"><select data-suggestion-status><option ${x.reviewStatus==='待审核'?'selected':''}>待审核</option><option ${x.reviewStatus==='已确认'?'selected':''}>已确认</option><option ${x.reviewStatus==='已修改'?'selected':''}>已修改</option><option ${x.reviewStatus==='需补充'?'selected':''}>需补充</option><option ${x.reviewStatus==='已排除'?'selected':''}>已排除</option></select></label></div><input class="suggestion-title-input" data-suggestion-title value="${escapeHtml(x.title||'')}"><textarea class="suggestion-content-input" data-suggestion-content>${escapeHtml(x.editableContent||x.content||'')}</textarea><div class="suggestion-evidence"><strong>依据</strong><span>${(x.basis||[]).map(b=>escapeHtml(`${b.name} ${b.value||''}`)).join('、')||'待补充'}</span>${(x.sources||[]).map(source=>`<small>来源：${escapeHtml(source.file||'未知文件')} · 第 ${source.page||'?'} 页</small>`).join('')}</div></article>`;
  const flat=suggestionState.suggestions;
  const grouped=suggestionState.modules.length?suggestionState.modules.map(module=>{const items=flat.filter(x=>x.sourceModuleId===module.moduleId||x.module===module.moduleTitle);return `<section class="module-review-group" data-module-id="${escapeHtml(module.moduleId||'')}"><div class="module-review-head"><div><strong>${escapeHtml(module.moduleTitle||module.title||module.moduleId)}</strong><small>${escapeHtml(module.status||'draft')} · ${items.length} 条建议</small></div><div><button type="button" class="secondary-button module-save" data-module-id="${escapeHtml(module.moduleId||'')}">保存本模块</button><button type="button" class="secondary-button module-confirm" data-module-id="${escapeHtml(module.moduleId||'')}">确认本模块</button></div></div>${items.map(x=>card(x,flat.indexOf(x))).join('')||`<p class="project-empty">${module.status==='missing_data'?'资料不足，待补充后生成。':'本模块暂无建议。'}</p>`}</section>`}).join('') : flat.map(card).join('');
  const content=grouped||'<p class="project-empty">没有基于已确认指标生成建议。</p>';
  $("#suggestion-list").innerHTML=content;
  const page=$("#suggestions-page-content");
  if(page){page.innerHTML=`<div class="suggestion-toolbar"><button class="secondary-button" id="page-confirm-all" type="button">确认全部</button><span class="connection-status">${escapeHtml(suggestionState.modeLabel||'标准模板')} · ${flat.length} 条</span></div><div class="period-fields"><label>干预周期<input id="page-intervention-period" value="${escapeHtml(data.interventionPeriod||'')}" /></label><label>复查周期<input id="page-review-period" value="${escapeHtml(data.reviewPeriod||'')}" /></label></div><div class="suggestion-list">${content}</div>`;$("#page-confirm-all")?.addEventListener('click',()=>document.querySelectorAll('#suggestions-page-content [data-suggestion-status]').forEach(x=>x.value='已确认'));}
  document.querySelectorAll('.module-save').forEach(button=>button.addEventListener('click',()=>saveModule(button.dataset.moduleId)));
  document.querySelectorAll('.module-confirm').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.moduleId;document.querySelectorAll(`[data-module-id="${CSS.escape(id)}"] [data-suggestion-status]`).forEach(x=>x.value='已确认');showStatus('本模块建议已选中，请保存审核')}));
  setIcons();
}



