async function openSuggestions(){if(!state.activeProjectId)return showStatus('请先打开一个项目',true);const d=await api(`/api/projects/${state.activeProjectId}/suggestions`);renderSuggestions(d);syncSuggestionPeriods(d);return d}
async function openSuggestionsPage(){loadOutputProfile();if(!state.activeProjectId)return showStatus('请先打开一个项目',true);try{const d=await api(`/api/projects/${state.activeProjectId}/suggestions`);renderSuggestions(d)}catch(e){showStatus(`建议加载失败：${e.message}`,true)}}
function syncSuggestionPeriods(data){if($("#intervention-period"))$("#intervention-period").value=data?.interventionPeriod||"";if($("#review-period"))$("#review-period").value=data?.reviewPeriod||""}
async function generateSuggestions(){
  if(!state.activeProjectId)return matrixNotice('请先打开一个项目','error');
  const button=$('#generate-suggestions-page')||$('#generate-suggestions');
  if(button.disabled)return;
  let feedback=$('#suggestion-generation-status');
  if(!feedback){feedback=document.createElement('p');feedback.id='suggestion-generation-status';feedback.setAttribute('role','status');button.parentElement.appendChild(feedback);}
  const label=button.innerHTML;button.disabled=true;button.textContent='正在生成…';
  feedback.textContent='正在读取报告指标并生成待审核建议，请稍候…';
  try{
    const mode=$('input[name="suggestion-mode"]:checked')?.value||'A';
    const data=await api('/api/projects/'+state.activeProjectId+'/suggestions',{method:'POST',body:JSON.stringify({mode})});
    renderSuggestions(data);syncSuggestionPeriods(data);
    const count=data.suggestions?.length||0;
    feedback.textContent=count?'已生成 '+count+' 条建议草稿，请逐条审核后用于 PPT。':'没有匹配到可生成建议的异常指标，请核对报告解析结果。';
    matrixNotice(feedback.textContent,count?'success':'error');
  }catch(error){feedback.textContent='建议生成失败：'+error.message;matrixNotice(feedback.textContent,'error');}
  finally{button.disabled=false;button.innerHTML=label;setIcons();}
}
async function generateDeepSeekSuggestions(){if(!state.activeProjectId)return showStatus('请先打开一个项目',true);const button=$("#generate-deepseek-suggestions");button.disabled=true;try{const current=await api(`/api/projects/${state.activeProjectId}/suggestions`);if(!Number(current.confirmedIndicatorCount||0)){renderSuggestions(current);showStatus(current.candidateIndicatorCount?'请先在病例审核中确认指标，再使用 DeepSeek':'当前没有候选指标，DeepSeek 没有可分析的输入',true);return}const d=await api(`/api/projects/${state.activeProjectId}/suggestions/model`,{method:'POST',body:JSON.stringify({config:{deepseek:state.config.deepseek}})});renderSuggestions(d);syncSuggestionPeriods(d);showStatus(`DeepSeek 已生成 ${d.suggestions?.length||0} 条建议，等待人工审核`)}catch(e){showStatus(`DeepSeek 建议生成失败：${e.message}`,true)}finally{button.disabled=false}}
async function saveModule(moduleId){try{const suggestions=collectSuggestions();const d=await api(`/api/projects/${state.activeProjectId}/suggestions`,{method:"PUT",body:JSON.stringify({suggestions,interventionPeriod:$("#page-intervention-period")?.value||"",reviewPeriod:$("#page-review-period")?.value||""})});renderSuggestions(d);showStatus("本模块审核已保存")}catch(e){showStatus(`本模块保存失败：${e.message}`,true)}}
function collectSuggestions(){const pageCards=Array.from(document.querySelectorAll('#suggestions-page-content .suggestion-card'));const cards=pageCards.length?pageCards:Array.from(document.querySelectorAll('#suggestion-list .suggestion-card'));return cards.map(card=>{const i=Number(card.dataset.suggestionIndex),old=suggestionState.suggestions[i]||{},status=card.querySelector('[data-suggestion-status]')?.value||old.reviewStatus||'待审核';return {...old,title:card.querySelector('[data-suggestion-title]')?.value.trim()||old.title,editableContent:card.querySelector('[data-suggestion-content]')?.value.trim()||old.content,content:card.querySelector('[data-suggestion-content]')?.value.trim()||old.content,reviewStatus:status}})}
async function saveSuggestions(requireConfirmed=false,fromPage=false){const suggestions=collectSuggestions();if(requireConfirmed&&suggestions.some(x=>x.reviewStatus!=='已确认'))return showStatus('仍有建议未确认，确认后才能用于 PPT',true);const d=await api(`/api/projects/${state.activeProjectId}/suggestions`,{method:'PUT',body:JSON.stringify({suggestions,interventionPeriod:$(fromPage?"#page-intervention-period":"#intervention-period")?.value.trim()||'',reviewPeriod:$(fromPage?"#page-review-period":"#review-period")?.value.trim()||''})});renderSuggestions(d);syncSuggestionPeriods(d);showStatus(requireConfirmed?'建议已确认，可进入 PPT':'建议审核结果已保存')}
