async function saveCase(reviewed=false){const c={patient:{},history:{},indicators:[],sources:[]};document.querySelectorAll("#case-form textarea").forEach(x=>{if(x.dataset.group)c[x.dataset.group][x.dataset.key]=x.value.trim()});document.querySelectorAll("#indicator-list .field").forEach((row,index)=>{const name=row.querySelector('[data-indicator]')?.value||"",value=row.querySelector('[data-indicator-value]')?.value||"";if(name)c.indicators.push({...originalIndicators[index],name,value,status:originalIndicators[index]?.status||"待确认",reviewStatus:row.querySelector('[data-indicator-review]')?.value||"待审核",dimension:row.querySelector('[data-indicator-dimension]')?.value||"待分类",source:{...originalIndicators[index]?.source,file:row.dataset.file||"",page:row.dataset.page?Number(row.dataset.page):null}})});await api(`/api/projects/${state.activeProjectId}/case`,{method:"PUT",body:JSON.stringify({caseData:c,reviewed})});await api(`/api/projects/${state.activeProjectId}/indicators`,{method:"PUT",body:JSON.stringify({indicators:c.indicators})});await loadProjects();renderProjects();$("#case-modal").classList.remove("open");showStatus(reviewed?"病例审核已确认":"病例草稿已保存")}
