function setWorkspaceMode(mode){document.body.classList.toggle('matrix-page-active',mode==='matrix');document.querySelectorAll('.workspace-mode').forEach(button=>button.classList.toggle('active',button.dataset.mode===mode));if(mode==='matrix'){setWorkflowStep(2);openMatrixPage()}else{document.querySelectorAll('.workflow-step').forEach(x=>x.classList.toggle('hidden',!x.classList.contains('workflow-step-1')));document.querySelector('.workflow-tab[data-step="1"]')?.classList.add('active')}}
