async function uploadMatrixScreenshots(files){
  const projectId=state.activeProjectId;
  if(!projectId){matrixNotice('请先打开一个项目','error');return;}
  const selected=Array.from(files||[]).filter(file=>/^image\/(png|jpeg|jpg)$/.test(file.type)||/\.(png|jpe?g)$/i.test(file.name));
  if(!selected.length){matrixNotice('请选择 PNG 或 JPG 截图','error');return;}
  let uploaded=0;
  for(const file of selected){
    if(file.size>20*1024*1024){matrixNotice(file.name+' 超过 20 MB，未上传','error');continue;}
    matrixNotice('正在添加截图：'+file.name+'…','pending');
    try{await api('/api/projects/'+projectId+'/upload',{method:'POST',body:JSON.stringify({name:file.name,size:file.size,kind:'screenshot',base64:await toBase64(file)})});uploaded++;}
    catch(error){matrixNotice(file.name+' 添加失败：'+error.message,'error');}
  }
  await loadProjects();
  if(uploaded){renderMatrixSourceFiles();matrixNotice('已成功添加 '+uploaded+' 张截图，请点击“识别截图并整理”。');}
}
function renderMatrixSourceFiles(){
  const project=state.projects.find(item=>item.id===state.activeProjectId),files=(project?.files||[]).filter(file=>file.kind==='screenshots'||file.kind==='screenshot');
  const box=$('#matrix-source-files');if(!box)return;
  box.innerHTML=files.length?'<div class="matrix-source-files-title">已添加截图 '+files.length+' 张</div>'+files.map(file=>'<div class="matrix-source-file"><span>🖼️ '+escapeHtml(file.originalName||file.name)+'</span><small>'+escapeHtml(file.status||'待识别')+'</small></div>').join(''):'<div class="matrix-source-files-empty">还没有添加截图</div>';
}
async function generateMatrixSources(){if(!state.activeProjectId)return matrixNotice('请先打开一个项目','error');const button=$('#matrix-generate');if(button?.disabled)return;const label=button?.innerHTML;try{if(button){button.disabled=true;button.innerHTML='<i data-lucide="loader-circle"></i>正在识别…';}matrixNotice('正在识别截图，请稍候…','pending');const d=await api('/api/projects/'+state.activeProjectId+'/matrix-workspace/generate',{method:'POST',body:'{}'});renderMatrixWorkspace(d.workspace);renderMatrixSourceFiles();const failed=(d.workspace?.sections||[]).flatMap(section=>section.candidateFacts||[]).filter(item=>/截图识别失败/.test(item.text||''));matrixNotice(failed.length?'截图已读取，但有 '+failed.length+' 张识别失败，请看分区中的失败原因。':'截图识别完成，候选内容已整理，请展开分区核对。',failed.length?'error':'success')}catch(e){matrixNotice('截图识别失败：'+e.message,'error')}finally{if(button){button.disabled=false;button.innerHTML=label;setIcons()}}}
$('#matrix-generate')?.addEventListener('click',generateMatrixSources);
$('#matrix-screenshot-input')?.addEventListener('change',async event=>{await uploadMatrixScreenshots(event.target.files);event.target.value=''})
document.addEventListener('click', async event => {
  const button = event.target.closest('#matrix-text-generate');
  if (!button || matrixTextBusy) return;
  const input = $('#matrix-text-input'), text = input?.value.trim(), projectId = state.activeProjectId;
  if (!projectId) return matrixNotice('请先打开一个项目。','error');
  if (!text) { matrixNotice('请先粘贴文字稿，再点击整理。','error'); input?.focus(); return; }
  matrixTextBusy = true;
  const original = button.innerHTML;
  button.disabled = true; button.textContent = '正在整理…'; button.setAttribute('aria-busy','true');
  const editors = [...document.querySelectorAll('#matrix-page-content textarea, #matrix-page-content button')];
  const disabledStates = editors.map(element => element.disabled);
  editors.forEach(element => element.disabled = true);
  matrixNotice('正在整理文字稿并匹配七个填写区，请稍候…','pending');
  try {
    const fields = matrixCoreDefinitions.map(field => ({...field, content:document.querySelector('[data-core-field="'+field.id+'"]')?.value || ''}));
    await api('/api/projects/'+projectId+'/matrix-workspace',{method:'PUT',body:JSON.stringify({workspace:{core:{central:'心理、精神、情绪',fields}}})});
    const data = await api('/api/projects/'+projectId+'/matrix-workspace/text',{method:'POST',body:JSON.stringify({text})});
    if (state.activeProjectId !== projectId) return matrixNotice('原项目的文字稿已整理，请返回该项目审核。');
    renderMatrixWorkspace(data.workspace);
    $('#matrix-text-input').value = text;
    const sectionCount = (data.workspace?.sections || []).filter(section => (section.candidateFacts || []).length || section.interpretation || (section.questions || []).some(question => question.answer)).length;
    matrixNotice('整理完成：已映射 '+(data.filledCoreCount || 0)+' 个中央功能框、'+sectionCount+' 个外围分区，请审核。');
  } catch (error) {
    matrixNotice('整理失败：'+error.message+'。文字稿已保留，可重试。','error');
  } finally {
    matrixTextBusy = false;
    editors.forEach((element,index)=>element.disabled=disabledStates[index]);
    button.disabled=false; button.innerHTML=original; button.removeAttribute('aria-busy');
  }
});
